import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../App.css";

const RateUser = () => {
  const [usersToRate, setUsersToRate] = useState([]);
  const [error, setError] = useState("");

  const userId = sessionStorage.getItem("userId");

  useEffect(() => {
    const fetchUsers = async () => {
      try {
        const res = await fetch(`${API_BASE_URL}/api/users`);
        const users = await res.json();

        const ratingsRes = await fetch(`${API_BASE_URL}/api/ratings/all`);
        const ratings = await ratingsRes.json();

        if (!Array.isArray(users)) {
          setError("Invalid data format received");
          return;
        }

        // Attach average rating to each user
        const enrichedUsers = users
          .filter((u) => String(u.id) !== String(userId))
          .map((u) => {
            const ratingObj = ratings.find((r) => r.rated_id === u.id);
            return {
              ...u,
              average_rating: ratingObj ? ratingObj.average_rating : "Not rated yet",
            };
          });

        setUsersToRate(enrichedUsers);
      } catch (err) {
        console.error("Error loading users or ratings:", err);
        setError("Failed to load users.");
      }
    };

    if (userId) {
      fetchUsers();
    }
  }, [userId]);

  const handleRate = async (ratedUserId, rating) => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/ratings`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          rater_id: userId,
          rated_id: ratedUserId,
          rating: rating,
        }),
      });

      if (res.ok) {
        alert("Rating submitted!");
      } else {
        alert("Failed to submit rating.");
      }
    } catch (err) {
      console.error("Rating error:", err);
      alert("Something went wrong.");
    }
  };

  return (
    <div>
      <Navbar />
      <main className="rate-user-wrapper">
        <h2>Rate Other Users</h2>
        {error && <p style={{ color: "red" }}>{error}</p>}
        {usersToRate.length === 0 && !error && <p>No users to rate yet.</p>}

        {usersToRate.map((user) => (
          <div className="rate-card" key={user.id}>
            <h4>{user.username}</h4>
            <p>Email: {user.email}</p>
            <p>Average Rating: {user.average_rating}</p>
            <div className="rating-buttons">
              {[1, 2, 3, 4, 5].map((n) => (
                <button key={n} onClick={() => handleRate(user.id, n)}>
                  {n}⭐
                </button>
              ))}
            </div>
          </div>
        ))}
      </main>
      <Footer />
    </div>
  );
};

export default RateUser;
